57	func TestBenchMainRedirectsExecutionSubcommands(t *testing.T) {
58		tests := []string{"matrix", "sweep", "run", "plan"}
59	
60		for _, subcommand := range tests {
61			t.Run(subcommand, func(t *testing.T) {
62				// Capture stderr
63				oldStderr := os.Stderr
64				r, w, _ := os.Pipe()
65				os.Stderr = w
66	
67				code := run([]string{subcommand})
68	
69				w.Close()
70				os.Stderr = oldStderr
71	
72				// Read captured stderr
73				var buf bytes.Buffer
74				io.Copy(&buf, r)
75				stderr := buf.String()
76	
77				if code != 2 {
78					t.Errorf("run([%s]) exit code = %d, want 2", subcommand, code)
79				}
80	
81				if !strings.Contains(stderr, "use ./benchmark") {
82					t.Errorf("run([%s]) stderr does not contain 'use ./benchmark', got: %q", subcommand, stderr)
83				}
84			})
85		}
86	}
